entries[71951] = { ["name"] = "Banner der Gefallenen", ["text"] = "Dieser Gegenstand startet eine Quest.\nBenötigt Stufe 15\n\"Beweis Eures Kampfesmuts. Jemand vom Dunkelmond-Jahrmarkt würde es sicherlich gern erwerben.\"" }
entries[71952] = { ["name"] = "Erobertes Insigne", ["text"] = "Dieser Gegenstand startet eine Quest.\nBenötigt Stufe 15\n\"Von einem bezwungenen Feind errungen. Jemand vom Dunkelmond-Jahrmarkt würde es sicherlich gern erwerben.\"" }
entries[71953] = { ["name"] = "Tagebuch eines gefallenen Abenteurers", ["text"] = "Dieser Gegenstand startet eine Quest.\nBenötigt Stufe 15\n\"Das Tagebuch enthält die Erzählungen der epischen Abenteuer eines gefallenen Feindes. Jemand vom Dunkelmond-Jahrmarkt würde es sicherlich gern erwerben.\"" }
entries[71954] = { ["name"] = "Zwielichtdrache des ruchlosen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 70\nBenötigt Gekonntes Reiten\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren Zwielichtdrachen des ruchlosen Gladiators oder gibt ihn wieder frei. Das ist ein Flugreittier." }
entries[71955] = { ["name"] = "Rezept: Tiefenheim-Iolith transmutieren", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Alchemie\n(525)\nBenutzen: Lehrt Euch die Transmutation eines Tiefenheim-Ioliths." }
entries[71956] = { ["name"] = "Rezept: Elfenperidot transmutieren", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Alchemie\n(525)\nBenutzen: Lehrt Euch die Transmutation eines Elfenperidots." }
entries[71957] = { ["name"] = "Rezept: Lichtgemme transmutieren", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Alchemie\n(525)\nBenutzen: Lehrt Euch die Transmutation einer Lichtgemme." }
entries[71958] = { ["name"] = "Rezept: Lavakoralle transmutieren", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Alchemie\n(525)\nBenutzen: Lehrt Euch die Transmutation einer Lavakoralle." }
entries[71959] = { ["name"] = "Rezept: Schattenspinell transmutieren", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Alchemie\n(525)\nBenutzen: Lehrt Euch die Transmutation eines Schattenspinells." }
entries[71960] = { ["name"] = "Rezept: Königinnengranat transmutieren", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Alchemie\n(525)\nBenutzen: Lehrt Euch die Transmutation eines Königinnengranats." }
entries[71961] = { ["name"] = "Fetter Frosch", ["text"] = "Questgegenstand\n\"Fett und saftig. Die perfekte Wahl für die klassische Leckerei des Dunkelmond-Jahrmarkts!\"" }
entries[71964] = { ["name"] = "Eisenbestände", ["text"] = "Questgegenstand\nBenutzen: Erschafft ein Hufeisen. Muss sich in der Nähe eines Amboss befinden.\n4 Aufladungen\n\"Standardisierte Eisenstäbe, bereit zur Weiterverarbeitung.\"" }
entries[71965] = { ["name"] = "Vorlage: Strassbesetzte Sonnenbrille", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Juwelenschleifen (525)\nBenutzen: Lehrt Euch die Herstellung von strassbesetzten Sonnenbrillen.\n\nStrassbesetzte Sonnenbrille\nKopf\nHaltbarkeit 30 / 30\nVerkaufspreis:\nBenötigt Echtgold (2), Schimärenauge (2), Hypnotischer Staub (8), Traumsmaragd (2)" }
entries[71966] = { ["name"] = "Glänzende Bronzeniete", ["text"] = "Verkaufspreis:" }
entries[71967] = { ["name"] = "Hufeisen", ["text"] = "Questgegenstand\nBenutzen: Beschlägt Baby mit ihren neuen Hufeisen. Benötigt 4 Hufeisen.\n\"Kunstfertigkeit, eines Königs würdig!\"" }
entries[71968] = { ["name"] = "Panzerschrott", ["text"] = "Questgegenstand\n\"Metallstücke, die im Kampf von Dampfpanzern abgesprengt wurden.\"" }
entries[71969] = { ["name"] = "Hammer des Dunkelmond-Jahrmarkts", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nWaffenhand\n1 - 3 Schaden Tempo 3.00\n(0.67 Schaden pro Sekunde)\nHaltbarkeit 16 / 16" }
entries[71970] = { ["name"] = "Gewinnlos des Dunkelmond-Jahrmarkts", ["text"] = "Wird beim Aufheben gebunden" }
entries[71971] = { ["name"] = "Bund exotischer Kräuter", ["text"] = "Questgegenstand\nBenutzen: Mahlt die in diesem Bündel enthaltenen Kräuter, um prophetische Tinte zu erschaffen.\n\"Duftig und exotisch, die meisten dieser Kräuter könnt Ihr nicht bestimmen.\"" }
entries[71972] = { ["name"] = "Prophetische Tinte", ["text"] = "Questgegenstand\nBenutzen: Beschriftet ein Blatt leichtes Pergament, um eins von Sayges Horoskopen zu erstellen.\n\"Magische Tinte von der gesagt wird, dass sie die Zukunft enthüllt.\"" }
entries[71974] = { ["name"] = "Wahrsagung", ["text"] = "Questgegenstand\nEinzigartig (5)\n\"Frisch geschriebene Worte weisen jedem die Zukunft, der Sayge befragt.\"" }
entries[71975] = { ["name"] = "Luftdruckgewehr", ["text"] = "Questgegenstand\nBenutzen: Ihr seid bereit, auf ein paar Ziele zu feuern!\n\"Ausschließlich für den Gebrauch am Schießstand. Kampfuntauglich.\"" }
entries[71976] = { ["name"] = "Preis des Dunkelmond-Jahrmarkts", ["text"] = "Questgegenstand\n\"Ein überdimensioniertes, lederbezogenes Stofftier mit großen Augen und einem freundlichen Lächeln.\"" }
entries[71977] = { ["name"] = "Handwerkerset des Dunkelmond-Jahrmarkts", ["text"] = "Questgegenstand\nBenutzen: Nutzt einen blauen Farbstoff, zwei glänzende Schmuckstücke und einen groben Faden, um einen Preis des Dunkelmond-Jahrmarkts herzustellen.\n\"Eine Tasche, die Leder, Nadeln und Muster für Handwerkerzwecke enthält.\"" }
entries[71978] = { ["name"] = "Bandage des Dunkelmond-Jahrmarkts", ["text"] = "Questgegenstand\nBenutzen: Verletzten Schausteller heilen.\n\"Mit Medizin getränkt, um die Heilung zu beschleunigen und Infektionen zu verhindern.\"" }
entries[71979] = { ["name"] = "Wahrsagerstaub", ["text"] = "Questgegenstand\n\"Ein glitzerndes, körniges Material zur Herstellung von Wahrsageausrüstung.\"" }
