entries[72042] = { ["name"] = "Allianzballon", ["text"] = "Wird beim Aufheben gebunden\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man dieses Spielzeug beschwört.\nMit Rechtsklick Euren Allianzballon beschwören oder wieder freigeben." }
entries[72043] = { ["name"] = "Cocktail-Shaker", ["text"] = "Questgegenstand\nBenutzen: Kombiniert 1 Mondbeerensaft mit 1 prickelnden Marktgetränk, um einen Mondbeerenfizz zu erschaffen.\n\"Ein Behälter, in dem Getränke aller Art gemischt werden können.\"" }
entries[72044] = { ["name"] = "Mondbeerenfizz", ["text"] = "Questgegenstand\n\"Es ist fruchtig! Es ist spritzig!\"" }
entries[72045] = { ["name"] = "Hordenballon", ["text"] = "Wird beim Aufheben gebunden\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man dieses Spielzeug beschwört.\nMit Rechtsklick Euren Hordenballon beschwören oder wieder freigeben." }
entries[72046] = { ["name"] = "Dunkelblüte", ["text"] = "Questgegenstand\n\"Der genaue Inhalt dieser Kräutermischung ist nur Mitarbeitern des Dunkelmond-Jahrmarkts bekannt.\"" }
entries[72047] = { ["name"] = "Luftgewehr des Dunkelmond-Jahrmarkts", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Ihr seid bereit, auf ein paar Ziele zu feuern!" }
entries[72048] = { ["name"] = "Bannerset des Dunkelmond-Jahrmarkts", ["text"] = "Questgegenstand\nBenutzen: Erschafft ein Banner des Dunkelmond-Jahrmarkts aus rotem Farbstoff, blauem Farbstoff und grobem Faden.\n\"Eine Sammlung von Stoffen und Mustern, um Dunkelmond-Banner herzustellen.\"" }
entries[72049] = { ["name"] = "Banner des Dunkelmond-Jahrmarkts", ["text"] = "Questgegenstand\nBenutzen: Steckt das Dunkelmond-Banner in einem Haufen loser Steine fest.\n\"Ein frisch geschneidertes Banner mit dem Logo des Dunkelmond-Jahrmarkts.\"" }
entries[72050] = { ["name"] = "Funkelnder 'Edelstein'", ["text"] = "Questgegenstand\n\"Nur ein Experte würde den Unterschied zwischen diesem Stück geschliffenem Glas und einem echten Edelstein erkennen.\"" }
entries[72052] = { ["name"] = "Stück zerbrochenen Glases", ["text"] = "Questgegenstand\nEinzigartig (5)\nBenutzen: Schleift ein unregelmäßiges Stück Glas zu einem falschen Edelstein.\n\"Ein Juwelier kann diese Stücke zerbrochenen Glases sicherlich in etwas Schönes verwandeln.\"" }
entries[72056] = { ["name"] = "Fette Frösche", ["text"] = "Questgegenstand\nBenutzen: Mit 5 herkömmlichen Mehl kombinieren, um Frösche im Teigmantel zu erschaffen.\n\"Nur die besten, biodynamisch gezogenen Frösche aus Freilandhaltung.\"" }
entries[72057] = { ["name"] = "Frosch im Teigmantel", ["text"] = "Questgegenstand\nBenutzen: Auf dem Dunkelmond-Jahrmarkt in den Topf hinter Stampf Donnerhorn werfen, um einen Knusperfrosch herzustellen.\n\"In Öl goldbraun und knusprig braten.\"" }
entries[72058] = { ["name"] = "Knusperfrosch", ["text"] = "Questgegenstand\n\"Der Favorit aller Jahrmarktsbesucher!\"" }
entries[72068] = { ["name"] = "Wächterjunges", ["text"] = "Benutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euer Wächterjunges beschwören oder wieder freigeben." }
entries[72070] = { ["name"] = "Handschuhe - Sturmangriff", ["text"] = "Benutzen: Handschuhe dauerhaft verzaubern, sodass die Angriffskraft um 26 erhöht wird. Benötigt einen Gegenstand der Stufe 35 oder höher.\nVerkaufspreis:" }
entries[72098] = { ["name"] = "Gewehr des Dunkelmond-Jahrmarkts", ["text"] = "Distanz\n2 - 3 Schaden Tempo 2.80\n(0.89 Schaden pro Sekunde)\nHaltbarkeit 18 / 18\nVerkaufspreis:" }
